 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The demos' common rule is a cyclic horizontal color band plus a diagonal
    # duplicate; for each row infer the band phase from its nonzero cells.
    palette = sorted({v for row in grid for v in row if v})
    n = len(palette)
    out = []
    for r in range(h):
        best_score, best_row = -1, None
        for phase in range(n):
            row = [palette[(phase + c) % n] for c in range(w)]
            score = sum(1 for c, v in enumerate(grid[r])
                        if v and (r == 0 or c != r) and v == row[c])
            if score > best_score:
                best_score, best_row = score, row
        if r > 0 and r < w:
            best_row[r] = best_row[r - 1]
        out.append(best_row)
    return out
